function validateTodo(todo) {
  return todo && todo.id && todo.title;
}

function filterTodos(todos, status) {
  return todos
    .filter(validateTodo)
    .filter(t => {
      if (status === 'active') return !t.completed;
      if (status === 'completed') return t.completed;
      return true;
    });
}

